9	  const scalar = {null:'null', boolean:'boolean', integer:'bigint', string:'string'};
10	  function visit(name) {
11	    if (selected.has(name)) return;
12	    if (!Object.hasOwn(definitions, name)) throw new Error('missing named schema: '+name);
13	    selected.add(name);
